"""GitHub source-code and configuration extraction (EXTRACTOR_VERSION).

Source code is knowledge-bearing and is kept verbatim (it is never removed
merely because it is code). Rejected instead, with a reason code:

* generated files (``@generated``, ``DO NOT EDIT``, ``Code generated by``, ...
  in the first 2 KiB), minified files (very long lines), and data dumps
  (mostly numeric/hex/base64 lines);
* vendored/dependency/build/cache paths and lockfiles (re-checked here with
  the acquisition lists, in case the file policy changed);
* license-only files (``LICENSE``/``COPYING``/``NOTICE``): boilerplate legal
  text repeated across millions of repositories;
* oversized configuration/data files.

``prose`` returns the natural-language part (comments and docstrings) used by
the English gate for code, since keywords and identifiers are not prose.
"""

from __future__ import annotations

import re

from app.sources.github.config import DEFAULT_EXCLUDED_DIRS
from app.sources.github.files import GENERATED_NAME, SECRET_NAME

CODE_EXTENSIONS = frozenset({".py", ".js", ".mjs", ".ts", ".java", ".go", ".rs", ".c", ".h", ".cc", ".cpp", ".hpp",
                             ".cs", ".rb", ".php", ".swift", ".kt", ".scala", ".sh", ".sql", ".r", ".jl", ".hs",
                             ".lua", ".pl", ".ex", ".erl", ".clj", ".dart", ".ml"})
CONFIG_EXTENSIONS = frozenset({".json", ".yaml", ".yml", ".toml", ".ini", ".cfg", ".xml", ".csv"})
CODE_FILENAMES = frozenset({"makefile", "dockerfile"})
LICENSE_FILENAMES = frozenset({"license", "licence", "copying", "notice", "unlicense"})
MAX_CONFIG_CHARS = 64 * 1024

_GENERATED_MARK = re.compile(
    r"@generated|do not edit|code generated by|auto-?generated|automatically generated|generated by the protocol "
    r"buffer compiler|this file (was|is) generated|generated from .{0,80} by|<auto-generated", re.I)
_DATA_LINE = re.compile(r"^[\s,;\[\]{}()\"'0-9a-fA-FxX+/=.:-]*$")
_HASH_COMMENT = frozenset({".py", ".rb", ".sh", ".r", ".jl", ".pl", ".ex", ".yaml", ".yml", ".toml", ".ini",
                           ".cfg", ""})
_SLASH_COMMENT = frozenset({".js", ".mjs", ".ts", ".java", ".go", ".rs", ".c", ".h", ".cc", ".cpp", ".hpp", ".cs",
                            ".php", ".swift", ".kt", ".scala", ".dart"})
_DASH_COMMENT = frozenset({".sql", ".lua", ".hs"})
_BLOCK_COMMENT = re.compile(r"/\*(.*?)\*/", re.S)
_ML_COMMENT = re.compile(r"\(\*(.*?)\*\)", re.S)
_DOCSTRING = re.compile(r'"""(.*?)"""|\'\'\'(.*?)\'\'\'', re.S)
_XML_COMMENT = re.compile(r"<!--(.*?)-->", re.S)
_COMMENT_DECORATION = re.compile(r"^[\s*#/!;%-]+")


class CodeRejection(ValueError):
    def __init__(self, code: str, message: str) -> None:
        super().__init__(message)
        self.code = code


def split_path(path: str) -> tuple[str, str]:
    """(lower-case file name, lower-case extension including the dot, or '')."""
    name = path.rsplit("/", 1)[-1].lower()
    dot = name.rfind(".")
    return name, (name[dot:] if dot > 0 else "")


def file_kind(path: str) -> str:
    """'markdown' | 'rst' | 'doc' | 'code' | 'config' | 'license' | 'unknown'."""
    name, ext = split_path(path)
    stem = name.split(".", 1)[0]
    if stem in LICENSE_FILENAMES:
        return "license"
    if ext in (".md", ".markdown", ".mdx"):
        return "markdown"
    if ext == ".rst":
        return "rst"
    if ext in (".txt", ".adoc", ".asciidoc", ".org", ".tex") or (not ext and stem in (
            "readme", "authors", "contributing", "changelog", "history", "install")):
        return "doc"
    if ext in CODE_EXTENSIONS or stem in CODE_FILENAMES:
        return "code"
    if ext in CONFIG_EXTENSIONS:
        return "config"
    return "unknown"


def path_rejection(path: str) -> str | None:
    """Re-check the acquisition path rules (vendored/build/cache dirs, lockfiles, secrets)."""
    segments = path.lower().split("/")
    excluded = set(DEFAULT_EXCLUDED_DIRS)
    if any(seg in excluded for seg in segments[:-1]):
        return "excluded_dir"
    name = segments[-1]
    if SECRET_NAME.match(name):
        return "secret_file"
    if GENERATED_NAME.match(name):
        return "generated_name"
    return None


def check_code(text: str, path: str) -> None:
    """Raise CodeRejection for generated, minified or data-dump content."""
    head = text[:2048]
    if _GENERATED_MARK.search(head):
        raise CodeRejection("generated", "generated-file marker in the header")
    lines = text.split("\n")
    non_empty = [line for line in lines if line.strip()]
    if not non_empty:
        return
    longest = max(len(line) for line in non_empty)
    average = sum(len(line) for line in non_empty) / len(non_empty)
    if longest > 1000 or (average > 200 and len(non_empty) < 20):
        raise CodeRejection("minified", "minified or single-line bundle")
    data_lines = sum(1 for line in non_empty if len(line) > 16 and _DATA_LINE.match(line))
    if len(non_empty) >= 20 and data_lines / len(non_empty) > 0.5:
        raise CodeRejection("data_dump", "mostly numeric/hex/base64 data lines")


def check_config(text: str) -> None:
    if len(text) > MAX_CONFIG_CHARS:
        raise CodeRejection("large_config", "configuration/data file larger than 64 KiB")
    check_code(text, "")


def prose(text: str, path: str) -> str:
    """Natural-language parts of a code/config file: comments and docstrings."""
    _name, ext = split_path(path)
    parts: list[str] = []
    if ext == ".py":
        parts += [a or b for a, b in _DOCSTRING.findall(text)]
    if ext in _SLASH_COMMENT or ext in (".css",):
        parts += _BLOCK_COMMENT.findall(text)
    if ext == ".ml":
        parts += _ML_COMMENT.findall(text)
    if ext == ".xml":
        parts += _XML_COMMENT.findall(text)
    for line in text.split("\n"):
        stripped = line.strip()
        if ext in _HASH_COMMENT and stripped.startswith("#") and not stripped.startswith("#!"):
            parts.append(stripped[1:])
        elif ext in _SLASH_COMMENT and "//" in stripped:
            if stripped.startswith("//"):
                parts.append(stripped[2:])
        elif ext in _DASH_COMMENT and stripped.startswith("--"):
            parts.append(stripped[2:])
        elif ext in (".erl", ".tex") and stripped.startswith("%"):
            parts.append(stripped[1:])
        elif ext == ".clj" and stripped.startswith(";"):
            parts.append(stripped.lstrip(";"))
    cleaned = [" ".join(_COMMENT_DECORATION.sub("", seg).split()) for part in parts for seg in part.split("\n")]
    return "\n".join(seg for seg in cleaned if seg)
